import{_ as i,c as n,o as r,ae as t}from"./chunks/framework.Bw0Gm4PQ.js";const f=JSON.parse('{"title":"REFORMING FOREIGN DEFENSE SALES TO IMPROVE","description":"","frontmatter":{"title":"REFORMING FOREIGN DEFENSE SALES TO IMPROVE","sourceUrl":"https://www.whitehouse.gov/presidential-actions/2025/04/reforming-foreign-defense-sales-to-improve-speed-and-accountability/","publishDate":"2025-04-09T18:25:21-04:00"},"headers":[],"relativePath":"executive-orders/2025-04-09-reforming-foreign-defense-sales-to-improve.md","filePath":"executive-orders/2025-04-09-reforming-foreign-defense-sales-to-improve.md"}'),s={name:"executive-orders/2025-04-09-reforming-foreign-defense-sales-to-improve.md"};function o(a,e,l,p,c,g){return r(),n("div",null,e[0]||(e[0]=[t('<h1 id="reforming-foreign-defense-sales-to-improve" tabindex="-1">REFORMING FOREIGN DEFENSE SALES TO IMPROVE <a class="header-anchor" href="#reforming-foreign-defense-sales-to-improve" aria-label="Permalink to &quot;REFORMING FOREIGN DEFENSE SALES TO IMPROVE&quot;">​</a></h1><p>Published: Wednesday, April 9, 2025</p><ul><li><p><strong>Purpose</strong>: To maintain a strong and technologically advanced U.S. military through a dynamic defense industrial base and effective partnerships.</p></li><li><p><strong>Objectives</strong>:</p><ul><li>Strengthen national security and ally capabilities through an improved foreign defense sales system.</li><li>Foster American supply chains, production, and technological development.</li></ul></li><li><p><strong>Policy Goals</strong>:</p><ul><li>Enhance accountability and transparency in foreign defense sales.</li><li>Streamline decision-making in military capability provisions to foreign countries.</li><li>Simplify rules and regulations for foreign defense sales.</li><li>Increase government-industry collaboration for efficiency in the Foreign Military Sales (FMS) program.</li><li>Promote U.S. competitiveness by integrating exportability in design and improving financing and contract flexibility.</li></ul></li><li><p><strong>Actions to be Taken</strong>:</p><ul><li><p><strong>Immediate Actions</strong>:</p><ul><li>Implement past national security policies and reassess existing restrictions on arms transfers.</li><li>Propose updates to congressional notification thresholds for arms sales.</li></ul></li><li><p><strong>Within 60 Days</strong>:</p><ul><li>Develop priority partner lists for conventional arms transfers.</li><li>Ensure priority items do not harm U.S. military readiness while advancing burden-sharing with allies.</li></ul></li><li><p><strong>Annual Reviews</strong>:</p><ul><li>Regular updates to priority partner and military end-item lists.</li></ul></li><li><p><strong>Plans to be Submitted</strong>:</p><ul><li>Within 90 days: Improve transparency metrics and technology security processes.</li><li>Within 120 days: Create a consolidated electronic tracking system for defense sales.</li></ul></li></ul></li><li><p><strong>Definitions</strong>:</p><ul><li><strong>Parallel Decision-Making</strong>: Simultaneous approvals in the FMS process to expedite decision-making.</li><li><strong>Exportability</strong>: Incorporating protection features in defense systems for export purposes.</li><li><strong>FMS-Only</strong>: Defense articles available exclusively through the FMS process.</li><li><strong>End-Item</strong>: The final deployable product.</li><li><strong>Foreign Defense Sales System</strong>: The framework for U.S. defense material transfer to international partners.</li></ul></li><li><p><strong>General Provisions</strong>:</p><ul><li>The order does not alter the legal authority of executive branches or create enforceable rights against the U.S. government.</li></ul></li></ul><p>Source: <a href="https://www.whitehouse.gov/presidential-actions/2025/04/reforming-foreign-defense-sales-to-improve-speed-and-accountability/" target="_blank" rel="noreferrer">https://www.whitehouse.gov/presidential-actions/2025/04/reforming-foreign-defense-sales-to-improve-speed-and-accountability/</a></p>',4)]))}const u=i(s,[["render",o]]);export{f as __pageData,u as default};
